def show_function_debug_output(func):
    if isinstance(func, Function):
        val = func.debug_buf.getvalue().strip()
        func.debug_buf.truncate(0)
        if val:
            from calibre.gui2.tweak_book.boss import get_boss
            get_boss().gui.sr_debug_output.show_log(func.name, val)


def reorder_files(names, order):
    reverse = order in {'spine-reverse', 'reverse-spine'}
    spine_order = {name: i for i, (name, is_linear) in enumerate(current_container().spine_names)}
    return sorted(frozenset(names), key=spine_order.get, reverse=reverse)


def _no_match_dialog(gui_parent, wrap, errfind):
    QApplication.restoreOverrideCursor()
    msg = '<p>' + _('No matches were found for %s') % ('<pre style="font-style:italic">' + prepare_string_for_xml(errfind) + '</pre>')
    if not wrap:
        msg += '<p>' + _('You have turned off search wrapping, so all text might not have been searched.'
                ' Try the search again, with wrapping enabled. Wrapping is enabled via the'
                ' "Wrap" checkbox at the bottom of the search panel.')
    return error_dialog(gui_parent, _('Not found'), msg, show=True)


def _no_replace_dialog(gui_parent, prefix=''):
    QApplication.restoreOverrideCursor()
    if prefix:
        prefix += ' '
    error_dialog(gui_parent, _('Cannot replace'), prefix + _('You must first click "Find", before trying to replace'), show=True)
    return False


def _count_message(gui_parent, replaced, count, errfind, show_diff=False, show_dialog=True):
    if show_dialog:
        if replaced:
            msg = _('Performed the replacement at {num} occurrences of {query}')
        else:
            msg = _('Found {num} occurrences of {query}')
        msg = msg.format(num=count, query=errfind)
        if show_diff and count > 0:
            d = MessageBox(MessageBox.INFO, _('Searching done'), prepare_string_for_xml(msg), parent=gui_parent, show_copy_button=False)
            d.diffb = b = d.bb.addButton(_('See what &changed'), d.bb.ActionRole)
            b.setIcon(QIcon(I('diff.png')))
            d.set_details(None)
            b.clicked.connect(d.accept)
            b.clicked.connect(partial(show_current_diff, allow_revert=True), type=Qt.QueuedConnection)
            d.exec_()
        else:
            info_dialog(gui_parent, _('Searching done'), prepare_string_for_xml(msg), show=True)


def _do_find(searches, editor, files, marked, wrap, errfind, gui_parent):
    for pattern, _ in searches:
        if editor is not None:
            if editor.find(pattern, marked=marked, save_match='gui'):
                return True
            if wrap and not files and editor.find(pattern, wrap=True, marked=marked, save_match='gui'):
                return True
        for fname, syntax in files.iteritems():
            ed = editors.get(fname, None)
            if ed is not None:
                if not wrap and ed is editor:
                    continue
                if ed.find(pattern, complete=True, save_match='gui'):
                    show_editor(fname)
                    return True
            else:
                raw = current_container().raw_data(fname)
                if pattern.search(raw) is not None:
                    edit_file(fname, syntax)
                    if editors[fname].find(pattern, complete=True, save_match='gui'):
                        return True
    return _no_match_dialog(gui_parent, wrap, errfind)


def _do_replace(searches, editor, gui_parent):
    if editor is None:
        return _no_replace_dialog(gui_parent)
    for pattern, repl in searches:
        repl_is_func = isinstance(repl, Function)
        if repl_is_func:
            repl.init_env(current_editor_name)
        if editor.replace(pattern, repl, saved_match='gui'):
            if repl_is_func:
                repl.end()
                show_function_debug_output(repl)
            return True
    return _no_replace_dialog(gui_parent, _('Currently selected text does not match the search query.'))


def _do_all(searches, files, replace, gui_parent, show_current_diff, add_savepoint, rewind_savepoint, set_modified):
    count = 0
    if not files:
        return 0
    lfiles = files or {current_editor_name: editor.syntax}
    updates = set()
    raw_data = {}
    for name in lfiles:
        raw_data[name] = editors[name].get_raw_data() if name in editors else current_container().raw_data(name)

    for pattern, repl in searches:
        repl_is_func = isinstance(repl, Function)
        iterator = lfiles
        if repl_is_func and repl.file_order is not None and len(lfiles) > 1:
            iterator = reorder_files(iterator, repl.file_order)
        for name in iterator:
            raw = raw_data[name]
            if replace:
                if repl_is_func:
                    repl.context_name = name
                raw, num = pattern.subn(repl, raw)
                if num:
                    updates.add(name)
                    raw_data[name] = raw
            else:
                num = len(pattern.findall(raw))
            count += num
        if repl_is_func:
            repl.end()
            show_function_debug_output(repl)

    for name in updates:
        raw = raw_data[name]
        if name in editors:
            editors[name].replace_data(raw)
        else:
            with current_container().open(name, 'wb') as f:
                f.write(raw.encode('utf-8'))
    QApplication.restoreOverrideCursor()
    _count_message(gui_parent, replace, count, errfind, show_diff=replace)
    return count


def run_search(
    searches, action, current_editor, current_editor_name, searchable_names,
    gui_parent, show_editor, edit_file, show_current_diff, add_savepoint, rewind_savepoint, set_modified):

    if isinstance(searches, dict):
        searches = [searches]

    editor, where, files, do_all, marked = initialize_search_request(searches[0], action, current_editor, current_editor_name, searchable_names)
    wrap = searches[0]['wrap']
    errfind = searches[0]['find'] if len(searches) == 1 else _('the selected searches')

    try:
        compiled = [(get_search_regex(s), get_search_function(s)) for s in searches]
    except InvalidRegex as e:
        return error_dialog(gui_parent, _('Invalid regex'), '<p>' + _(
            'The regular expression you entered is invalid: <pre>{0}</pre>With error: {1}').format(
                prepare_string_for_xml(e.regex), e.message), show=True)
    except NoSuchFunction as e:
        return error_dialog(gui_parent, _('No such function'), '<p>' + _(
            'No replace function with the name: %s exists') % prepare_string_for_xml(e.message), show=True)

    with BusyCursor():
        if action == 'find':
            return _do_find(compiled, editor, files, marked, wrap, errfind, gui_parent)
        if action == 'replace':
            return _do_replace(compiled, editor, gui_parent)
        if action == 'replace-find':
            if _do_replace(compiled, editor, gui_parent):
                return _do_find(compiled, editor, files, marked, wrap, errfind, gui_parent)
            return False
        if action == 'replace-all':
            if marked:
                show_result_dialog = True
                for _, repl in compiled:
                    if getattr(getattr(repl, 'func', None), 'suppress_result_dialog', False):
                        show_result_dialog = False
                        break
                total = sum(editor.all_in_marked(p, repl) for p, repl in compiled)
                return _count_message(gui_parent, True, total, errfind, show_dialog=show_result_dialog)
            add_savepoint(_('Before: Replace all'))
            total = _do_all(compiled, files, True, gui_parent, show_current_diff, add_savepoint, rewind_savepoint, set_modified)
            if total == 0:
                rewind_savepoint()
            else:
                set_modified()
            return
        if action == 'count':
            if marked:
                total = sum(editor.all_in_marked(p) for p, _ in compiled)
                return _count_message(gui_parent, False, total, errfind)
            return _do_all(compiled, files, False, gui_parent, show_current_diff, add_savepoint, rewind_savepoint, set_modified)


if __name__ == '__main__':
    app = QApplication([])
    d = SavedSearches()
    d.show()
    app.exec_()

