  @VisibleForTesting
  List<String> getEntityTypes() throws IOException {
    LeveldbIterator iterator = null;
    try {
      iterator = getDbIterator(false);
      List<String> entityTypes = new ArrayList<>();
      iterator.seek(ENTITY_ENTRY_PREFIX);
      while (iterator.hasNext()) {
        byte[] key = iterator.peekNext().getKey();
        if (key[0] != ENTITY_ENTRY_PREFIX[0]) {
          break;
        }
        String type = new KeyParser(key, ENTITY_ENTRY_PREFIX.length).getNextString();
        entityTypes.add(type);
        byte[] lookupKey = KeyBuilder.newInstance()
            .add(ENTITY_ENTRY_PREFIX)
            .add(type)
            .getBytesForLookup();
        if (lookupKey[lookupKey.length - 1] != 0x0) {
          throw new IOException("Found unexpected end byte in lookup key");
        }
        lookupKey[lookupKey.length - 1] = 0x1;
        iterator.seek(lookupKey);
      }
      return entityTypes;
    } catch (DBException e) {
      throw new IOException(e);
    } finally {
      IOUtils.cleanup(LOG, iterator);
    }
  }

  private void deleteKeysWithPrefix(WriteBatch writeBatch, byte[] prefix,
      LeveldbIterator iterator) {
    for (iterator.seek(prefix); iterator.hasNext(); iterator.next()) {
      byte[] key = iterator.peekNext().getKey();
      if (!prefixMatches(prefix, prefix.length, key)) {
        break;
      }
      writeBatch.delete(key);
    }
  }

  @VisibleForTesting
  boolean deleteNextEntity(String entityType, byte[] reverseTimestamp,
      LeveldbIterator iterator, LeveldbIterator pfIterator, boolean seeked)
      throws IOException {
    WriteBatch writeBatch = null;
    try {
      KeyBuilder kb = KeyBuilder.newInstance()
          .add(ENTITY_ENTRY_PREFIX)
          .add(entityType);
      byte[] typePrefix = kb.getBytesForLookup();
      kb.add(reverseTimestamp);
      if (!seeked) {
        iterator.seek(kb.getBytesForLookup());
      }
      if (!iterator.hasNext()) {
        return false;
      }
      byte[] entityKey = iterator.peekNext().getKey();
      if (!prefixMatches(typePrefix, typePrefix.length, entityKey)) {
        return false;
      }
      KeyParser kp = new KeyParser(entityKey, typePrefix.length + 8);
      String entityId = kp.getNextString();
      int prefixlen = kp.getOffset();
      byte[] deletePrefix = Arrays.copyOf(entityKey, prefixlen);
      writeBatch = db.createWriteBatch();
      LOG.debug("Deleting entity type:" + entityType + " id:" + entityId);
      writeBatch.delete(createStartTimeLookupKey(entityId, entityType));
      EntityIdentifier ei = new EntityIdentifier(entityId, entityType);
      startTimeReadCache.remove(ei);
      startTimeWriteCache.remove(ei);
      while (iterator.hasNext()) {
        byte[] key = iterator.peekNext().getKey();
        if (!prefixMatches(entityKey, prefixlen, key)) {
          break;
        }
        writeBatch.delete(key);
        if (key.length == prefixlen) {
          continue;
        }
        byte column = key[prefixlen];
        if (column == PRIMARY_FILTERS_COLUMN[0]) {
          handlePrimaryFilterDeletion(writeBatch, key, deletePrefix, pfIterator);
        } else if (column == RELATED_ENTITIES_COLUMN[0]) {
          handleRelatedEntityDeletion(writeBatch, key, entityId, entityType);
        } else if (column == INVISIBLE_REVERSE_RELATED_ENTITIES_COLUMN[0]) {
          handleReverseRelatedDeletion(writeBatch, key, entityId, entityType);
        }
      }
      WriteOptions wo = new WriteOptions();
      wo.sync(true);
      db.write(writeBatch, wo);
      return true;
    } catch (DBException e) {
      throw new IOException(e);
    } finally {
      IOUtils.cleanup(LOG, writeBatch);
    }
  }

  private void handlePrimaryFilterDeletion(WriteBatch writeBatch, byte[] key,
      byte[] deletePrefix, LeveldbIterator pfIterator) throws IOException {
    KeyParser kp = new KeyParser(key, deletePrefix.length + PRIMARY_FILTERS_COLUMN.length);
    String name = kp.getNextString();
    Object value = GenericObjectMapper.read(key, kp.getOffset());
    deleteKeysWithPrefix(writeBatch, addPrimaryFilterToKey(name, value, deletePrefix), pfIterator);
    LOG.debug("Deleting entity primary filter entry " + name + " " + value);
  }

  private void handleRelatedEntityDeletion(WriteBatch writeBatch, byte[] key,
      String entityId, String entityType) throws IOException {
    KeyParser kp = new KeyParser(key, key.length - (RELATED_ENTITIES_COLUMN.length + entityId.length() + entityType.length()));
    String type = kp.getNextString();
    String id = kp.getNextString();
    byte[] relatedStart = getStartTime(id, type);
    if (relatedStart == null) {
      LOG.warn("Found no start time for related entity " + id + " of type " + type);
      return;
    }
    writeBatch.delete(createReverseRelatedEntityKey(id, type, relatedStart, entityId, entityType));
    LOG.debug("Deleting invisible reverse related entity entry");
  }

  private void handleReverseRelatedDeletion(WriteBatch writeBatch, byte[] key,
      String entityId, String entityType) throws IOException {
    KeyParser kp = new KeyParser(key, key.length - (INVISIBLE_REVERSE_RELATED_ENTITIES_COLUMN.length + entityId.length() + entityType.length()));
    String type = kp.getNextString();
    String id = kp.getNextString();
    byte[] relatedStart = getStartTime(id, type);
    if (relatedStart == null) {
      LOG.warn("Found no start time for reverse related entity " + id + " of type " + type);
      return;
    }
    writeBatch.delete(createRelatedEntityKey(id, type, relatedStart, entityId, entityType));
    LOG.debug("Deleting forward related entity entry");
  }

  @VisibleForTesting
  void discardOldEntities(long timestamp) throws IOException, InterruptedException {
    byte[] reverseTimestamp = writeReverseOrderedLong(timestamp);
    long totalCount = 0;
    long t1 = System.currentTimeMillis();
    List<String> entityTypes = getEntityTypes();
    for (String entityType : entityTypes) {
      LeveldbIterator iterator = null;
      LeveldbIterator pfIterator = null;
      long typeCount = 0;
      try {
        deleteLock.writeLock().lock();
        iterator = getDbIterator(false);
        pfIterator = getDbIterator(false);
        if (deletionThread != null && deletionThread.isInterrupted()) {
          throw new InterruptedException();
        }
        boolean seeked = false;
        while (deleteNextEntity(entityType, reverseTimestamp, iterator, pfIterator, seeked)) {
          typeCount++;
          totalCount++;
          seeked = true;
          if (deletionThread != null && deletionThread.isInterrupted()) {
            throw new InterruptedException();
          }
        }
      } catch (IOException e) {
        LOG.error("Got IOException while deleting entities for type " + entityType, e);
      } finally {
        IOUtils.cleanup(LOG, iterator, pfIterator);
        deleteLock.writeLock().unlock();
        if (typeCount > 0) {
          LOG.info("Deleted " + typeCount + " entities of type " + entityType);
        }
      }
    }
    long t2 = System.currentTimeMillis();
    LOG.info("Discarded " + totalCount + " entities for timestamp " + timestamp + " and earlier in " + (t2 - t1) / 1000.0 + " seconds");
  }

  @VisibleForTesting
  LeveldbIterator getDbIterator(boolean fillCache) {
    ReadOptions ro = new ReadOptions();
    ro.fillCache(fillCache);
    return new LeveldbIterator(db, ro);
  }

  Version loadVersion() throws IOException {
    try {
      byte[] data = db.get(bytes(TIMELINE_STORE_VERSION_KEY));
      if (data == null || data.length == 0) {
        return getCurrentVersion();
      }
      return new VersionPBImpl(VersionProto.parseFrom(data));
    } catch (DBException e) {
      throw new IOException(e);
    }
  }

  @VisibleForTesting
  void storeVersion(Version state) throws IOException {
    dbStoreVersion(state);
  }

  private void dbStoreVersion(Version state) throws IOException {
    try {
      db.put(bytes(TIMELINE_STORE_VERSION_KEY), ((VersionPBImpl) state).getProto().toByteArray());
    } catch (DBException e) {
      throw new IOException(e);
    }
  }

  Version getCurrentVersion() {
    return CURRENT_VERSION_INFO;
  }

  private void checkVersion() throws IOException {
    Version loaded = loadVersion();
    LOG.info("Loaded timeline store version info " + loaded);
    if (loaded.equals(getCurrentVersion())) {
      return;
    }
    if (loaded.isCompatibleTo(getCurrentVersion())) {
      LOG.info("Storing timeline store version info " + getCurrentVersion());
      dbStoreVersion(CURRENT_VERSION_INFO);
    } else {
      String msg = "Incompatible version for timeline store: expecting version " + getCurrentVersion() + ", but loading version " + loaded;
      LOG.fatal(msg);
      throw new IOException(msg);
    }
  }

  @Override
  public void put(TimelineDomain domain) throws IOException {
    WriteBatch writeBatch = null;
    try {
      writeBatch = db.createWriteBatch();
      validateDomain(domain);
      writeDomainDescription(writeBatch, domain);
      writeDomainOwner(writeBatch, domain);
      writeDomainReaders(writeBatch, domain);
      writeDomainWriters(writeBatch, domain);
      writeDomainTimestamps(writeBatch, domain);
      db.write(writeBatch);
    } catch (DBException e) {
      throw new IOException(e);
    } finally {
      IOUtils.cleanup(LOG, writeBatch);
    }
  }

  private void validateDomain(TimelineDomain domain) {
    if (domain.getId() == null || domain.getId().isEmpty()) {
      throw new IllegalArgumentException("Domain doesn't have an ID");
    }
    if (domain.getOwner() == null || domain.getOwner().isEmpty()) {
      throw new IllegalArgumentException("Domain doesn't have an owner.");
    }
  }

  private void writeDomainDescription(WriteBatch writeBatch, TimelineDomain domain) throws IOException {
    byte[] entryKey = createDomainEntryKey(domain.getId(), DESCRIPTION_COLUMN);
    byte[] lookupKey = createOwnerLookupKey(domain.getOwner(), domain.getId(), DESCRIPTION_COLUMN);
    byte[] value = domain.getDescription() != null ?
        domain.getDescription().getBytes(Charset.forName("UTF-8")) : EMPTY_BYTES;
    writeBatch.put(entryKey, value);
    writeBatch.put(lookupKey, value);
  }

  private void writeDomainOwner(WriteBatch writeBatch, TimelineDomain domain) throws IOException {
    byte[] entryKey = createDomainEntryKey(domain.getId(), OWNER_COLUMN);
    byte[] lookupKey = createOwnerLookupKey(domain.getOwner(), domain.getId(), OWNER_COLUMN);
    byte[] value = domain.getOwner().getBytes(Charset.forName("UTF-8"));
    writeBatch.put(entryKey, value);
    writeBatch.put(lookupKey, value);
  }

  private void writeDomainReaders(WriteBatch writeBatch, TimelineDomain domain) throws IOException {
    byte[] entryKey = createDomainEntryKey(domain.getId(), READER_COLUMN);
    byte[] lookupKey = createOwnerLookupKey(domain.getOwner(), domain.getId(), READER_COLUMN);
    byte[] value = (domain.getReaders() != null && !domain.getReaders().isEmpty()) ?
        domain.getReaders().getBytes(Charset.forName("UTF-8")) : EMPTY_BYTES;
    writeBatch.put(entryKey, value);
    writeBatch.put(lookupKey, value);
  }

  private void writeDomainWriters(WriteBatch writeBatch, TimelineDomain domain) throws IOException {
    byte[] entryKey = createDomainEntryKey(domain.getId(), WRITER_COLUMN);
    byte[] lookupKey = createOwnerLookupKey(domain.getOwner(), domain.getId(), WRITER_COLUMN);
    byte[] value = (domain.getWriters() != null && !domain.getWriters().isEmpty()) ?
        domain.getWriters().getBytes(Charset.forName("UTF-8")) : EMPTY_BYTES;
    writeBatch.put(entryKey, value);
    writeBatch.put(lookupKey, value);
  }

  private void writeDomainTimestamps(WriteBatch writeBatch, TimelineDomain domain) throws IOException {
    byte[] entryKey = createDomainEntryKey(domain.getId(), TIMESTAMP_COLUMN);
    byte[] lookupKey = createOwnerLookupKey(domain.getOwner(), domain.getId(), TIMESTAMP_COLUMN);
    long now = System.currentTimeMillis();
    byte[] timestamps = db.get(entryKey);
    if (timestamps == null) {
      timestamps = new byte[16];
      writeReverseOrderedLong(now, timestamps, 0);
      writeReverseOrderedLong(now, timestamps, 8);
    } else {
      writeReverseOrderedLong(now, timestamps, 8);
    }
    writeBatch.put(entryKey, timestamps);
    writeBatch.put(lookupKey, timestamps);
  }

  private static byte[] createDomainEntryKey(String domainId,
      byte[] columnName) throws IOException {
    return KeyBuilder.newInstance()
        .add(DOMAIN_ENTRY_PREFIX)
        .add(domainId)
        .add(columnName)
        .getBytes();
  }

  private static byte[] createOwnerLookupKey(
      String owner, String domainId, byte[] columnName) throws IOException {
    return KeyBuilder.newInstance()
        .add(OWNER_LOOKUP_PREFIX)
        .add(owner)
        .add(domainId)
        .add(columnName)
        .getBytes();
  }

  @Override
  public TimelineDomain getDomain(String domainId) throws IOException {
    LeveldbIterator iterator = null;
    try {
      byte[] prefix = KeyBuilder.newInstance()
          .add(DOMAIN_ENTRY_PREFIX)
          .add(domainId)
          .getBytesForLookup();
      iterator = new LeveldbIterator(db);
      iterator.seek(prefix);
      return readDomainFromIterator(iterator, domainId, prefix);
    } catch (DBException e) {
      throw new IOException(e);
    } finally {
      IOUtils.cleanup(LOG, iterator);
    }
  }

  private static TimelineDomain readDomainFromIterator(LeveldbIterator iterator,
      String domainId, byte[] prefix) throws IOException {
    TimelineDomain domain = new TimelineDomain();
    domain.setId(domainId);
    boolean empty = true;
    while (iterator.hasNext()) {
      iterator.next();
      byte[] key = iterator.peekNext().getKey();
      if (!prefixMatches(prefix, prefix.length, key)) {
        break;
      }
      empty = false;
      byte[] value = iterator.peekNext().getValue();
      if (value == null || value.length == 0) {
        continue;
      }
      byte column = key[prefix.length];
      if (column == DESCRIPTION_COLUMN[0]) {
        domain.setDescription(new String(value, Charset.forName("UTF-8")));
      } else if (column == OWNER_COLUMN[0]) {
        domain.setOwner(new String(value, Charset.forName("UTF-8")));
      } else if (column == READER_COLUMN[0]) {
        domain.setReaders(new String(value, Charset.forName("UTF-8")));
      } else if (column == WRITER_COLUMN[0]) {
        domain.setWriters(new String(value, Charset.forName("UTF-8")));
      } else if (column == TIMESTAMP_COLUMN[0]) {
        domain.setCreatedTime(readReverseOrderedLong(value, 0));
        domain.setModifiedTime(readReverseOrderedLong(value, 8));
      } else {
        LOG.error("Unrecognized domain column: " + column);
      }
    }
    return empty ? null : domain;
  }

  @Override
  public TimelineDomains getDomains(String owner) throws IOException {
    LeveldbIterator iterator = null;
    try {
      byte[] prefix = KeyBuilder.newInstance()
          .add(OWNER_LOOKUP_PREFIX)
          .add(owner)
          .getBytesForLookup();
      List<TimelineDomain> domains = new ArrayList<>();
      iterator = new LeveldbIterator(db);
      for (iterator.seek(prefix); iterator.hasNext(); iterator.next()) {
        byte[] key = iterator.peekNext().getKey();
        if (!prefixMatches(prefix, prefix.length, key)) {
          break;
        }
        String domainId = new KeyParser(key, prefix.length).getNextString();
        byte[] domainPrefix = KeyBuilder.newInstance()
            .add(OWNER_LOOKUP_PREFIX)
            .add(owner)
            .add(domainId)
            .getBytesForLookup();
        TimelineDomain domain = readDomainFromIterator(iterator, domainId, domainPrefix);
        if (domain != null) {
          domains.add(domain);
        }
      }
      domains.sort(this::compareDomains);
      TimelineDomains result = new TimelineDomains();
      result.addDomains(domains);
      return result;
    } catch (DBException e) {
      throw new IOException(e);
    } finally {
      IOUtils.cleanup(LOG, iterator);
    }
  }

  private int compareDomains(TimelineDomain d1, TimelineDomain d2) {
    int cmp = d2.getCreatedTime().compareTo(d1.getCreatedTime());
    return cmp != 0 ? cmp : d2.getModifiedTime().compareTo(d1.getModifiedTime());
  }

  private int compareBytes(byte[] o1, byte[] o2) {
    return WritableComparator.compareBytes(o1, 0, o1.length, o2, 0, o2.length);
  }
