  private void initEventHandlers() {
    eventHandlers.put(SchedulerEvent.Type.NODE_ADDED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleNodeAdded(e); } });
    eventHandlers.put(SchedulerEvent.Type.NODE_REMOVED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleNodeRemoved(e); } });
    eventHandlers.put(SchedulerEvent.Type.NODE_UPDATE,
        new EventHandler() { public void handle(SchedulerEvent e) { handleNodeUpdate(e); } });
    eventHandlers.put(SchedulerEvent.Type.APP_ADDED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleAppAdded(e); } });
    eventHandlers.put(SchedulerEvent.Type.APP_REMOVED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleAppRemoved(e); } });
    eventHandlers.put(SchedulerEvent.Type.NODE_RESOURCE_UPDATE,
        new EventHandler() { public void handle(SchedulerEvent e) { handleNodeResourceUpdate(e); } });
    eventHandlers.put(SchedulerEvent.Type.APP_ATTEMPT_ADDED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleAppAttemptAdded(e); } });
    eventHandlers.put(SchedulerEvent.Type.APP_ATTEMPT_REMOVED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleAppAttemptRemoved(e); } });
    eventHandlers.put(SchedulerEvent.Type.CONTAINER_EXPIRED,
        new EventHandler() { public void handle(SchedulerEvent e) { handleContainerExpired(e); } });
  }

  private interface EventHandler {
    void handle(SchedulerEvent event);
  }

  private void handleNodeAdded(SchedulerEvent event) {
    if (!(event instanceof NodeAddedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    NodeAddedSchedulerEvent nodeAddedEvent = (NodeAddedSchedulerEvent) event;
    addNode(nodeAddedEvent.getAddedRMNode());
    recoverContainersOnNode(nodeAddedEvent.getContainerReports(),
        nodeAddedEvent.getAddedRMNode());
  }

  private void handleNodeRemoved(SchedulerEvent event) {
    if (!(event instanceof NodeRemovedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    NodeRemovedSchedulerEvent nodeRemovedEvent = (NodeRemovedSchedulerEvent) event;
    removeNode(nodeRemovedEvent.getRemovedRMNode());
  }

  private void handleNodeUpdate(SchedulerEvent event) {
    if (!(event instanceof NodeUpdateSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    NodeUpdateSchedulerEvent nodeUpdatedEvent = (NodeUpdateSchedulerEvent) event;
    nodeUpdate(nodeUpdatedEvent.getRMNode());
  }

  private void handleAppAdded(SchedulerEvent event) {
    if (!(event instanceof AppAddedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    AppAddedSchedulerEvent appAddedEvent = (AppAddedSchedulerEvent) event;
    String queueName = resolveReservationQueueName(appAddedEvent.getQueue(),
        appAddedEvent.getApplicationId(),
        appAddedEvent.getReservationID());
    if (queueName != null) {
      addApplication(appAddedEvent.getApplicationId(),
          queueName, appAddedEvent.getUser(),
          appAddedEvent.getIsAppRecovering());
    }
  }

  private void handleAppRemoved(SchedulerEvent event) {
    if (!(event instanceof AppRemovedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    AppRemovedSchedulerEvent appRemovedEvent = (AppRemovedSchedulerEvent) event;
    removeApplication(appRemovedEvent.getApplicationID(),
        appRemovedEvent.getFinalState());
  }

  private void handleNodeResourceUpdate(SchedulerEvent event) {
    if (!(event instanceof NodeResourceUpdateSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    NodeResourceUpdateSchedulerEvent nodeResourceUpdatedEvent =
        (NodeResourceUpdateSchedulerEvent) event;
    updateNodeResource(nodeResourceUpdatedEvent.getRMNode(),
        nodeResourceUpdatedEvent.getResourceOption());
  }

  private void handleAppAttemptAdded(SchedulerEvent event) {
    if (!(event instanceof AppAttemptAddedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    AppAttemptAddedSchedulerEvent appAttemptAddedEvent =
        (AppAttemptAddedSchedulerEvent) event;
    addApplicationAttempt(appAttemptAddedEvent.getApplicationAttemptId(),
        appAttemptAddedEvent.getTransferStateFromPreviousAttempt(),
        appAttemptAddedEvent.getIsAttemptRecovering());
  }

  private void handleAppAttemptRemoved(SchedulerEvent event) {
    if (!(event instanceof AppAttemptRemovedSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    AppAttemptRemovedSchedulerEvent appAttemptRemovedEvent =
        (AppAttemptRemovedSchedulerEvent) event;
    removeApplicationAttempt(
        appAttemptRemovedEvent.getApplicationAttemptID(),
        appAttemptRemovedEvent.getFinalAttemptState(),
        appAttemptRemovedEvent.getKeepContainersAcrossAppAttempts());
  }

  private void handleContainerExpired(SchedulerEvent event) {
    if (!(event instanceof ContainerExpiredSchedulerEvent)) {
      throw new RuntimeException("Unexpected event type: " + event);
    }
    ContainerExpiredSchedulerEvent containerExpiredEvent =
        (ContainerExpiredSchedulerEvent) event;
    ContainerId containerId = containerExpiredEvent.getContainerId();
    completedContainer(getRMContainer(containerId),
        SchedulerUtils.createAbnormalContainerStatus(
            containerId,
            SchedulerUtils.EXPIRED_CONTAINER),
        RMContainerEventType.EXPIRE);
  }

  @Override
  public void handle(SchedulerEvent event) {
    EventHandler handler = eventHandlers.get(event.getType());
    if (handler != null) {
      handler.handle(event);
    } else {
      LOG.error("Unknown event arrived at FairScheduler: " + event);
    }
  }

  private void validateConf(Configuration conf) {
    int minMem = conf.getInt(
      YarnConfiguration.RM_SCHEDULER_MINIMUM_ALLOCATION_MB,
      YarnConfiguration.DEFAULT_RM_SCHEDULER_MINIMUM_ALLOCATION_MB);
    int maxMem = conf.getInt(
      YarnConfiguration.RM_SCHEDULER_MAXIMUM_ALLOCATION_MB,
      YarnConfiguration.DEFAULT_RM_SCHEDULER_MAXIMUM_ALLOCATION_MB);

    if (minMem < 0 || minMem > maxMem) {
      throw new YarnRuntimeException("Invalid resource scheduler memory"
        + " allocation configuration"
        + ", " + YarnConfiguration.RM_SCHEDULER_MINIMUM_ALLOCATION_MB
        + "=" + minMem
        + ", " + YarnConfiguration.RM_SCHEDULER_MAXIMUM_ALLOCATION_MB
        + "=" + maxMem + ", min should equal greater than 0"
        + ", max should be no smaller than min.");
    }

    int minVcores = conf.getInt(
      YarnConfiguration.RM_SCHEDULER_MINIMUM_ALLOCATION_VCORES,
      YarnConfiguration.DEFAULT_RM_SCHEDULER_MINIMUM_ALLOCATION_VCORES);
    int maxVcores = conf.getInt(
      YarnConfiguration.RM_SCHEDULER_MAXIMUM_ALLOCATION_VCORES,
      YarnConfiguration.DEFAULT_RM_SCHEDULER_MAXIMUM_ALLOCATION_VCORES);

    if (minVcores < 0 || minVcores > maxVcores) {
      throw new YarnRuntimeException("Invalid resource scheduler vcores"
        + " allocation configuration"
        + ", " + YarnConfiguration.RM_SCHEDULER_MINIMUM_ALLOCATION_VCORES
        + "=" + minVcores
        + ", " + YarnConfiguration.RM_SCHEDULER_MAXIMUM_ALLOCATION_VCORES
        + "=" + maxVcores + ", min should equal greater than 0"
        + ", max should be no smaller than min.");
    }
  }

  public FairSchedulerConfiguration getConf() {
    return conf;
  }

  public QueueManager getQueueManager() {
    return queueMgr;
